package main
import("encoding/json";"flag";"fmt";"os";"path/filepath";"github.com/chrisbirster/battlebunnywealth/internal/publictestnet")
func main(){action:=flag.String("action","address","keygen|address|sign");walletPath:=flag.String("wallet","data/test-carrot/wallet.key","TEST-CARROT wallet key path");network:=flag.String("network","bbw-pop-public-testnet-v1","public testnet network id");to:=flag.String("to","","recipient TEST-CARROT address");amount:=flag.Int64("amount-atoms",0,"amount in CARROT atoms");fee:=flag.Int64("fee-atoms",0,"fee in CARROT atoms");nonce:=flag.Uint64("nonce",0,"sender nonce");validUntil:=flag.Uint64("valid-until",0,"last valid testnet height");flag.Parse();switch *action{case"keygen":w,err:=publictestnet.GenerateWallet();if err!=nil{fatal(err)};if err:=os.MkdirAll(filepath.Dir(*walletPath),0o700);err!=nil{fatal(err)};if err:=publictestnet.SaveWallet(*walletPath,w);err!=nil{fatal(err)};_=json.NewEncoder(os.Stdout).Encode(map[string]any{"address":w.Address(),"publicKey":w.PublicText(),"wallet":*walletPath,"asset":"TEST-CARROT","economicValue":false});case"address":w,err:=publictestnet.LoadWallet(*walletPath);if err!=nil{fatal(err)};_=json.NewEncoder(os.Stdout).Encode(map[string]any{"address":w.Address(),"publicKey":w.PublicText(),"asset":"TEST-CARROT","economicValue":false});case"sign":w,err:=publictestnet.LoadWallet(*walletPath);if err!=nil{fatal(err)};if *to==""||*validUntil==0{fatal(fmt.Errorf("-to and -valid-until are required"))};tx,err:=publictestnet.NewSignedTransaction(*network,*to,*amount,*fee,*nonce,*validUntil,w);if err!=nil{fatal(err)};_=json.NewEncoder(os.Stdout).Encode(tx);default:fatal(fmt.Errorf("unknown action %q",*action))}}
func fatal(err error){fmt.Fprintln(os.Stderr,"carrot-wallet:",err);os.Exit(1)}
